import asyncio
from async_bridge import run_sync


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently, returning results in input order.
    Any coroutine not finishing within `seconds` is cancelled and its result is None.
    Can be called repeatedly from synchronous code."""

    async def _run_all_with_deadline(coros, timeout):
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=timeout)
        # Cancel pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        for task in pending:
            try:
                await task
            except asyncio.CancelledError:
                pass
        # Collect results in input order, None for cancelled or errored tasks
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    results.append(None)
            else:
                results.append(None)
        return results

    return run_sync(_run_all_with_deadline(coros, seconds))

