import asyncio
from async_bridge import run_sync


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently from synchronous code, returning results in input order.
    Any coroutine not finishing within `seconds` is cancelled and returns None."""
    async def _run_all_with_deadline():
        tasks = [asyncio.create_task(c) for c in coros]
        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel pending tasks
        for task in pending:
            task.cancel()
        # Gather results from done tasks, None for cancelled
        results = []
        for task in tasks:
            if task in done:
                try:
                    results.append(task.result())
                except Exception:
                    # Propagate exceptions from finished tasks
                    raise
            else:
                results.append(None)
        return results

    return run_sync(_run_all_with_deadline())
